@@ -0,0 +1,76 @@
+// async stdlib createTodoStore with frozen {list,get,add,update,toggle,remove}
+// strict persisted array validation including exact keys and duplicate IDs
+// missing reads no-write; get missing undefined
+// add canonicalizes trimmed text/default false
+// update patch keys text/done only
+// missing mutation ids NOT_FOUND
+// atomic unique same-dir temp persistence and corrupt non-overwrite
+
+import { promises as fs } from 'fs';
+import { join } from 'path';
+
+const DB_FILE = join(__dirname, 'todo.db');
+
+async function createTodoStore() {
+  const db = await fs.readFile(DB_FILE, 'utf-8');
+  const todos = db ? JSON.parse(db) : [];
+
+  // Validate todos
+  const validTodos = todos.filter(todo => {
+    return (
+      typeof todo.id === 'string' &&
+      typeof todo.text === 'string' &&
+      typeof todo.done === 'boolean' &&
+      !todos.some(t => t.id === todo.id)
+    );
+  });
+
+  // Ensure unique IDs
+  const uniqueTodos = validTodos.filter((todo, index, array) => {
+    return array.findIndex(t => t.id === todo.id) === index;
+  });
+
+  // Persist to file
+  try {
+    await fs.writeFile(DB_FILE, JSON.stringify(uniqueTodos, null, 2));
+  } catch (err) {
+    console.error('Error writing to DB file:', err);
+  }
+
+  return Object.freeze({
+    list: () => uniqueTodos,
+    get: (id) => uniqueTodos.find(todo => todo.id === id) || undefined,
+    add: async (text, defaultDone = false) => {
+      if (!text || text.trim() === '') return;
+      const newTodo = {
+        id: Math.random().toString(36).substr(2, 9),
+        text: text.trim(),
+        done: defaultDone
+      };
+      uniqueTodos.push(newTodo);
+      await fs.writeFile(DB_FILE, JSON.stringify(uniqueTodos, null, 2));
+    },
+    update: async (id, updates) => {
+      const todo = uniqueTodos.find(todo => todo.id === id);
+      if (!todo) return;
+      if (updates.text !== undefined) todo.text = updates.text.trim();
+      if (updates.done !== undefined) todo.done = updates.done;
+      await fs.writeFile(DB_FILE, JSON.stringify(uniqueTodos, null, 2));
+    },
+    toggle: async (id) => {
+      const todo = uniqueTodos.find(todo => todo.id === id);
+      if (!todo) return;
+      todo.done = !todo.done;
+      await fs.writeFile(DB_FILE, JSON.stringify(uniqueTodos, null, 2));
+    },
+    remove: async (id) => {
+      const index = uniqueTodos.findIndex(todo => todo.id === id);
+      if (index !== -1) {
+        uniqueTodos.splice(index, 1);
+        await fs.writeFile(DB_FILE, JSON.stringify(uniqueTodos, null, 2));
+      }
+    }
+  });
+}
+
+export default createTodoStore;

